  1	using System.IO;
  2	using LoadOrderKeeper.Models;
  3	
  4	namespace LoadOrderKeeper.Services
  5	{
  6	    public static class DiffService
  7	    {
  8	        private static readonly ViewTexts.LocalizationService _localization = ViewTexts.LocalizationService.Instance;
  9	
 10	        public static async Task<IReadOnlyList<DiffLineModel>> GetPluginsDiffAsync(AppConfigModel config)
 11	        {
 12	            if (config is null)
 13	            {
 14	                throw new ArgumentNullException(nameof(config));
 15	            }
 16	
 17	            if (!config.IsValid())
 18	            {
 19	                throw new InvalidOperationException("Configuration paths are invalid.");
 20	            }
 21	
 22	            string targetPath = config.GetPluginsFilePath();
 23	            string referencePath = config.GetReferenceFilePath();
 24	
 25	            if (!File.Exists(referencePath))
 26	            {
 27	                throw new FileNotFoundException("Reference file not found.", referencePath);
 28	            }
 29	
 30	            if (!File.Exists(targetPath))
 31	            {
 32	                throw new FileNotFoundException("Plugins file not found.", targetPath);
 33	            }
 34	
 35	            var diffs = await FileService.GetModDiffAsync(config).ConfigureAwait(false);
 36	            var result = new List<DiffLineModel>();
 37	            var replacements = DetectReplacements(diffs, out var matchedAdditions);
 38	
 39	            // Calculate maxReferenceNumber as the highest CURRENT position of any reference mod
 40	            // This tells us "after which current position are mods truly 'added' vs 'inserted'"
 41	            var referenceDiffs = diffs.Where(d => d.ReferenceNumber.HasValue).ToList();
 42	            var existingReferenceMods = referenceDiffs.Where(d => d.CurrentNumber.HasValue).ToList();
 43	            int maxReferenceNumber = existingReferenceMods.Any() 
 44	                ? existingReferenceMods.Max(d => d.CurrentNumber!.Value) 
 45	                : 0;
 46	
 47	            foreach (var diff in diffs)
 48	            {
 49	                string displayName = diff.FileName;
 50	                if (replacements.TryGetValue(diff, out var replacement))
 51	                {
 52	                    int? lineNumber = diff.ReferenceNumber ?? replacement.CurrentNumber;
 53	                    string text = _localization.GetString("DiffDialog", "ReplacedText_Description", displayName, replacement.FileName, lineNumber ?? 0);
 54	                    result.Add(new DiffLineModel(displayName, text, DiffChangeType.Replaced, diff.ReferenceNumber, replacement.CurrentNumber, replacement.FileName));
 55	                }
 56	                else if (diff.IsRemoved)
 57	                {
 58	                    string text = _localization.GetString("DiffDialog", "RemovedText_Description", diff.ReferenceNumber ?? 0, displayName);
 59	                    result.Add(new DiffLineModel(displayName, text, DiffChangeType.Removed, diff.ReferenceNumber, diff.CurrentNumber));
 60	                }
 61	                else if (diff.IsNew)
 62	                {
 63	                    if (matchedAdditions.Contains(diff))
 64	                    {
 65	                        continue;
 66	                    }
 67	
 68	                    bool isInserted = diff.CurrentNumber.HasValue && diff.CurrentNumber.Value <= maxReferenceNumber;
 69	                    DiffChangeType changeType = isInserted ? DiffChangeType.Inserted : DiffChangeType.Added;
 70	                    string actionText = isInserted 
 71	                        ? _localization.GetString("DiffDialog", "InsertedText_Action")
 72	                        : _localization.GetString("DiffDialog", "AddedText_Action");
 73	                    string text = _localization.GetString("DiffDialog", "ModChangeText_Description", diff.CurrentNumber ?? 0, displayName, actionText);
 74	                    result.Add(new DiffLineModel(displayName, text, changeType, diff.ReferenceNumber, diff.CurrentNumber));
 75	                }
 76	                else if (diff.IsMoved)
 77	                {
 78	                    string text = _localization.GetString("DiffDialog", "MovedText_Description", displayName, diff.ReferenceNumber ?? 0, diff.CurrentNumber ?? 0);
 79	                    result.Add(new DiffLineModel(displayName, text, DiffChangeType.Moved, diff.ReferenceNumber, diff.CurrentNumber));
 80	                }
 81	            }
 82	
 83	            DetectAndAssignDependentChanges(result);
 84	
 85	            return result;
 86	        }
 87	
 88	        /// <summary>
 89	        /// Checks if there are any moved mods that are NOT part of dependent change lists.
 90	        /// These independent moves indicate external reordering that sorting could fix.
 91	        /// </summary>
 92	        public static async Task<bool> HasIndependentMovedModsAsync(AppConfigModel config)
 93	        {
 94	            if (config is null)
 95	            {
 96	                throw new ArgumentNullException(nameof(config));
 97	            }
 98	
 99	            if (!config.IsValid())
100	            {

101	                return false;
102	            }
103	
104	            string targetPath = config.GetPluginsFilePath();
105	            string referencePath = config.GetReferenceFilePath();
106	
107	            if (!File.Exists(referencePath) || !File.Exists(targetPath))
108	            {
109	                return false;
110	            }
111	
112	            var diffLines = await GetPluginsDiffAsync(config).ConfigureAwait(false);
113	            
114	            // Get all mods that are part of dependent change lists
115	            var dependentMods = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
116	            foreach (var line in diffLines)
117	            {
118	                foreach (var dependent in line.DependentChanges)
119	                {
120	                    dependentMods.Add(dependent.FileName);
121	                }
122	            }
123	            
124	            // Check if there are any moved mods that are NOT in the dependent set
125	            bool hasIndependentMoves = diffLines.Any(line => 
126	                line.ChangeType == DiffChangeType.Moved && 
127	                !dependentMods.Contains(line.FileName));
128	            
129	            return hasIndependentMoves;
130	        }
131	
132	        private static void DetectAndAssignDependentChanges(List<DiffLineModel> allLines)
133	        {
134	            var dependentLines = new HashSet<DiffLineModel>();
135	
136	            // Get all moved mods sorted by reference position
137	            var movedByReferencePos = allLines
138	                .Where(line => line.ChangeType == DiffChangeType.Moved && 
139	                              line.ReferenceNumber.HasValue && 
140	                              line.CurrentNumber.HasValue)
141	                .OrderBy(line => line.ReferenceNumber!.Value)
142	                .ToList();
143	
144	            // Process removed mods (they use reference positions)
145	            var removedMods = allLines
146	                .Where(line => line.ChangeType == DiffChangeType.Removed && line.ReferenceNumber.HasValue)
147	                .OrderBy(line => line.ReferenceNumber!.Value)
148	                .ToList();
149	
150	            foreach (var removed in removedMods)
151	            {
152	                int startPos = removed.ReferenceNumber!.Value + 1;
153	
154	                // Find next removed mod that would stop this one's range
155	                var nextRemoved = removedMods
156	                    .Where(r => r != removed && r.ReferenceNumber!.Value >= startPos)
157	                    .OrderBy(r => r.ReferenceNumber!.Value)
158	                    .FirstOrDefault();
159	
160	                int? stopBefore = nextRemoved?.ReferenceNumber;
161	
162	                // Collect moved mods in this range
163	                foreach (var moved in movedByReferencePos)
164	                {
165	                    if (dependentLines.Contains(moved))
166	                        continue;
167	
168	                    int refPos = moved.ReferenceNumber!.Value;
169	                    if (refPos < startPos)
170	                        continue;
171	                    if (stopBefore.HasValue && refPos >= stopBefore.Value)
172	                        break;
173	
174	                    removed.DependentChanges.Add(moved);
175	                    dependentLines.Add(moved);
176	                }
177	            }
178	
179	            // Process inserted mods (they affect mods from their insertion point onward)
180	            var insertedMods = allLines
181	                .Where(line => line.ChangeType == DiffChangeType.Inserted && line.CurrentNumber.HasValue)
182	                .OrderBy(line => line.CurrentNumber!.Value)
183	                .ToList();
184	
185	            foreach (var inserted in insertedMods)
186	            {
187	                // Find the reference position where this insertion occurs
188	                // This is the first moved mod at or after the insertion's current position
189	                var firstAffected = movedByReferencePos
190	                    .Where(m => !dependentLines.Contains(m) && m.CurrentNumber >= inserted.CurrentNumber)
191	                    .OrderBy(m => m.CurrentNumber)
192	                    .FirstOrDefault();
193	
194	                if (firstAffected == null)
195	                    continue;
196	
197	                int startRefPos = firstAffected.ReferenceNumber!.Value;
198	
199	                // Find next inserted or removed mod that would stop this range
200	                var nextInserted = insertedMods
201	                    .Where(i => i != inserted && i.CurrentNumber > inserted.CurrentNumber)
202	                    .OrderBy(i => i.CurrentNumber)
203	                    .FirstOrDefault();
204	
205	                var nextRemoved = removedMods
206	                    .Where(r => r.ReferenceNumber >= startRefPos)
207	                    .OrderBy(r => r.ReferenceNumber)
208	                    .FirstOrDefault();
209	
210	                // Use whichever comes first in reference coordinates
211	                int? stopBefore = null;
212	                if (nextRemoved != null)
213	                {
214	                    stopBefore = nextRemoved.ReferenceNumber!.Value;
215	                }
216	
217	                // Collect moved mods starting from the affected position
218	                foreach (var moved in movedByReferencePos)
219	                {
220	                    if (dependentLines.Contains(moved))
221	                        continue;
222	
223	                    int refPos = moved.ReferenceNumber!.Value;
224	                    if (refPos < startRefPos)
225	                        continue;
226	                    if (stopBefore.HasValue && refPos >= stopBefore.Value)
227	                        break;
228	
229	                    inserted.DependentChanges.Add(moved);
230	                    dependentLines.Add(moved);
231	                }
232	            }
233	
234	            // Remove all dependent changes from the main list
235	            allLines.RemoveAll(line => dependentLines.Contains(line));
236	        }
237	
238	        /// <summary>
239	        /// Computes the Longest Common Subsequence of two string lists using a standard
240	        /// dynamic-programming approach. Returns a list of paired (refIndex, curIndex) tuples
241	        /// representing the LCS in order, where refIndex is the position in
242	        /// <paramref name="reference"/> and curIndex is the position in <paramref name="current"/>.
243	        /// </summary>
244	        internal static List<(int refIndex, int curIndex)> ComputeLcs(
245	            IReadOnlyList<string> reference,
246	            IReadOnlyList<string> current,
247	            StringComparer comparer)
248	        {
249	            int m = reference.Count;
250	            int n = current.Count;
251	
252	            // Build DP table
253	            var dp = new int[m + 1, n + 1];
254	            for (int i = 1; i <= m; i++)
255	            {
256	                for (int j = 1; j <= n; j++)
257	                {
258	                    if (comparer.Equals(reference[i - 1], current[j - 1]))
259	                    {
260	                        dp[i, j] = dp[i - 1, j - 1] + 1;
261	                    }
262	                    else
263	                    {
264	                        dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]);
265	                    }
266	                }
267	            }
268	
269	            // Backtrack to recover the LCS pairs
270	            var result = new List<(int refIndex, int curIndex)>(dp[m, n]);
271	            int ri = m, ci = n;
272	            while (ri > 0 && ci > 0)
273	            {
274	                if (comparer.Equals(reference[ri - 1], current[ci - 1]))
275	                {
276	                    result.Add((ri - 1, ci - 1));
277	                    ri--;
278	                    ci--;
279	                }
280	                else if (dp[ri - 1, ci] >= dp[ri, ci - 1])
281	                {
282	                    ri--;
283	                }
284	                else
285	                {
286	                    ci--;
287	                }
288	            }
289	
290	            result.Reverse();
291	            return result;
292	        }
293	
294	        /// <summary>
295	        /// Classifies changes between <paramref name="reference"/> and <paramref name="current"/>
296	        /// mod lists given the pre-computed LCS alignment. Returns a flat list of
297	        /// <see cref="DiffLineModel"/> entries (dependents are nested under their causal change).
298	        /// </summary>
299	        /// <remarks>
300	        /// Classification pipeline:
301	        /// <list type="number">
302	        ///   <item>Items in the LCS whose absolute positions differ → candidate shifted (Moved).</item>
303	        ///   <item>Same-filename reconciliation: removed mod whose filename also appears in the new
304	        ///         set → Moved (swapped); performed before replacement detection.</item>
305	        ///   <item>Replacement detection: removed item at reference position R paired with the new
306	        ///         item at the corresponding LCS-aligned current position → Replaced.</item>
307	        ///   <item>Remaining new items classified as Added (beyond all surviving reference mods)
308	        ///         or Inserted (within the range of surviving reference mods).</item>
309	        ///   <item>Shifted LCS items grouped as dependent changes under their causal
310	        ///         insertion/deletion and removed from the top-level list.</item>
311	        /// </list>
312	        /// </remarks>
313	        internal static List<DiffLineModel> ClassifyChanges(
314	            IReadOnlyList<ModEntryModel> reference,
315	            IReadOnlyList<ModEntryModel> current,
316	            List<(int refIndex, int curIndex)> lcs)
317	        {
318	            // --- Step 0: Build fast lookup sets ---
319	            var lcsRefIndices = new HashSet<int>();
320	            var lcsCurIndices = new HashSet<int>();
321	            foreach (var (ri, ci) in lcs)
322	            {
323	                lcsRefIndices.Add(ri);
324	                lcsCurIndices.Add(ci);
325	            }
326	
327	            // Items in reference not in LCS → Removed candidates
328	            var removedMods = new List<ModEntryModel>();
329	            for (int i = 0; i < reference.Count; i++)
330	            {
331	                if (!lcsRefIndices.Contains(i))
332	                {
333	                    removedMods.Add(reference[i]);
334	                }
335	            }
336	
337	            // Items in current not in LCS → New candidates
338	            var newMods = new List<ModEntryModel>();
339	            for (int j = 0; j < current.Count; j++)
340	            {
341	                if (!lcsCurIndices.Contains(j))
342	                {
343	                    newMods.Add(current[j]);
344	                }
345	            }
346	
347	            // --- Step 1: LCS-shifted items (same relative order, different absolute position) ---
348	            // These are the "moved due to neighbour insertion/deletion" entries that will become
349	            // dependent changes. We track them but don't emit them as top-level entries yet.
350	            var lcsShifted = new List<(ModEntryModel mod, int refPos, int curPos)>();

351	            foreach (var (ri, ci) in lcs)
352	            {
353	                int refPos = reference[ri].LineNumber ?? (ri + 1);
354	                int curPos = current[ci].LineNumber ?? (ci + 1);
355	                if (refPos != curPos)
356	                {
357	                    lcsShifted.Add((reference[ri], refPos, curPos));
358	                }
359	            }
360	
361	            // --- Step 2: Same-filename reconciliation (Moved / swapped) ---
362	            var newByFilename = new Dictionary<string, ModEntryModel>(StringComparer.OrdinalIgnoreCase);
363	            foreach (var m in newMods)
364	            {
365	                newByFilename.TryAdd(m.FileName, m);
366	            }
367	
368	            var movedResults = new List<DiffLineModel>();
369	            var reconciledRemovedFilenames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
370	            // ReferenceEqualityComparer.Instance is intentional: ModEntryModel.Equals() compares by
371	            // FileName, so the default comparer would incorrectly de-duplicate two distinct instances
372	            // with the same filename. Identity comparison ensures we track the exact objects matched.
373	            var reconciledNewMods = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
374	
375	            foreach (var removed in removedMods)
376	            {
377	                if (newByFilename.TryGetValue(removed.FileName, out var matchingNew))
378	                {
379	                    // Same filename appeared in both removed and new → swapped/moved
380	                    string text = _localization.GetString("DiffDialog", "MovedText_Description",
381	                        removed.FileName,
382	                        removed.LineNumber ?? 0,
383	                        matchingNew.LineNumber ?? 0);
384	                    movedResults.Add(new DiffLineModel(
385	                        removed.FileName, text, DiffChangeType.Moved,
386	                        removed.LineNumber, matchingNew.LineNumber));
387	
388	                    reconciledRemovedFilenames.Add(removed.FileName);
389	                    reconciledNewMods.Add(matchingNew);
390	                }
391	            }
392	
393	            // Remove reconciled items from working sets
394	            var remainingRemoved = removedMods
395	                .Where(m => !reconciledRemovedFilenames.Contains(m.FileName))
396	                .ToList();
397	            var remainingNew = newMods
398	                .Where(m => !reconciledNewMods.Contains(m))
399	                .ToList();
400	
401	            // --- Step 3: Replacement detection (LCS-aligned position matching) ---
402	            // Build a map from current-list positions of new items for quick lookup
403	            var newByCurPos = new Dictionary<int, ModEntryModel>();
404	            foreach (var m in remainingNew)
405	            {
406	                int pos = m.LineNumber ?? 0;
407	                // pos == 0 means LineNumber was null (no position assigned); skip — these entries
408	                // cannot participate in replacement matching and will be classified as Added.
409	                if (pos > 0 && !newByCurPos.ContainsKey(pos))
410	                {
411	                    newByCurPos[pos] = m;
412	                }
413	            }
414	
415	            // For each removed mod, determine its aligned current position.
416	            // The expected current position of a removed mod at reference position R is:
417	            //   R − (number of other removed mods at reference positions < R)
418	            // because each earlier deletion shifts the surviving items up by one slot.
419	
420	            // ReferenceEqualityComparer.Instance: same rationale as reconciledNewMods above —
421	            // we need object identity to avoid conflating two distinct ModEntryModel instances
422	            // that happen to share the same filename.
423	            var replacements = new Dictionary<ModEntryModel, ModEntryModel>(ReferenceEqualityComparer.Instance);
424	            var usedForReplacement = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
425	
426	            // Sort removed mods by reference position for sequential processing
427	            var removedByRefPos = remainingRemoved
428	                .OrderBy(m => m.LineNumber ?? 0)
429	                .ToList();
430	
431	            int cumulativeDeletions = 0;
432	            foreach (var removed in removedByRefPos)
433	            {
434	                int refPos = removed.LineNumber ?? 0;
435	                // Aligned current position = reference position offset by cumulative prior deletions
436	                int alignedCurPos = refPos - cumulativeDeletions;
437	
438	                if (newByCurPos.TryGetValue(alignedCurPos, out var candidate)
439	                    && !usedForReplacement.Contains(candidate))
440	                {
441	                    replacements[removed] = candidate;
442	                    usedForReplacement.Add(candidate);
443	                }
444	                cumulativeDeletions++;
445	            }
446	
447	            // --- Step 4: Classify remaining new mods as Added or Inserted ---
448	            // maxSurvivingRefCurPos = highest current position of a mod that existed in reference
449	            // (either in LCS or as a moved/replacement pair)
450	            int maxSurvivingRefCurPos = 0;
451	            foreach (var (ri, ci) in lcs)
452	            {
453	                int curPos = current[ci].LineNumber ?? (ci + 1);
454	                if (curPos > maxSurvivingRefCurPos)
455	                    maxSurvivingRefCurPos = curPos;
456	            }
457	            // Also consider replacements: the replacement's current position counts as
458	            // "still within the reference range"
459	            foreach (var replacement in replacements.Values)
460	            {
461	                int curPos = replacement.LineNumber ?? 0;
462	                if (curPos > maxSurvivingRefCurPos)
463	                    maxSurvivingRefCurPos = curPos;
464	            }
465	
466	            // --- Step 5: Build the top-level result list ---
467	            var result = new List<DiffLineModel>();
468	
469	            // Replacement entries
470	            foreach (var removed in removedByRefPos)
471	            {
472	                if (replacements.TryGetValue(removed, out var replacement))
473	                {
474	                    int? lineNumber = removed.LineNumber ?? replacement.LineNumber;
475	                    string text = _localization.GetString("DiffDialog", "ReplacedText_Description",
476	                        removed.FileName, replacement.FileName, lineNumber ?? 0);
477	                    result.Add(new DiffLineModel(
478	                        removed.FileName, text, DiffChangeType.Replaced,
479	                        removed.LineNumber, replacement.LineNumber, replacement.FileName));
480	                }
481	                else
482	                {
483	                    // Truly removed
484	                    string text = _localization.GetString("DiffDialog", "RemovedText_Description",
485	                        removed.LineNumber ?? 0, removed.FileName);
486	                    result.Add(new DiffLineModel(
487	                        removed.FileName, text, DiffChangeType.Removed,
488	                        removed.LineNumber, null));
489	                }
490	            }
491	
492	            // Moved (swapped) entries
493	            result.AddRange(movedResults);
494	
495	            // Inserted / Added entries (new mods not used as replacements)
496	            foreach (var newMod in remainingNew)
497	            {
498	                if (usedForReplacement.Contains(newMod))
499	                    continue;
500	
501	                int curPos = newMod.LineNumber ?? 0;
502	                bool isInserted = curPos > 0 && curPos <= maxSurvivingRefCurPos;
503	                DiffChangeType changeType = isInserted ? DiffChangeType.Inserted : DiffChangeType.Added;
504	                string actionText = isInserted
505	                    ? _localization.GetString("DiffDialog", "InsertedText_Action")
506	                    : _localization.GetString("DiffDialog", "AddedText_Action");
507	                string text = _localization.GetString("DiffDialog", "ModChangeText_Description",
508	                    curPos, newMod.FileName, actionText);
509	                result.Add(new DiffLineModel(
510	                    newMod.FileName, text, changeType,
511	                    null, newMod.LineNumber));
512	            }
513	
514	            // LCS-shifted entries (dependent Moved)
515	            var shiftedLines = new List<DiffLineModel>();
516	            foreach (var (mod, refPos, curPos) in lcsShifted)
517	            {
518	                string text = _localization.GetString("DiffDialog", "MovedText_Description",
519	                    mod.FileName, refPos, curPos);
520	                shiftedLines.Add(new DiffLineModel(
521	                    mod.FileName, text, DiffChangeType.Moved,
522	                    refPos, curPos));
523	            }
524	
525	            // --- Step 6: Group shifted (dependent) lines under their causal change ---
526	            if (shiftedLines.Count > 0)
527	            {
528	                // Causal changes are insertions and removals (true removals, not replacements)
529	                var causalChanges = result
530	                    .Where(r => r.ChangeType == DiffChangeType.Inserted || r.ChangeType == DiffChangeType.Removed)
531	                    .OrderBy(r => r.ChangeType == DiffChangeType.Inserted ? r.CurrentNumber ?? 0 : r.ReferenceNumber ?? 0)
532	                    .ToList();
533	
534	                var assignedShifted = new HashSet<DiffLineModel>(ReferenceEqualityComparer.Instance);
535	
536	                foreach (var causal in causalChanges)
537	                {
538	                    foreach (var shifted in shiftedLines)
539	                    {
540	                        if (assignedShifted.Contains(shifted))
541	                            continue;
542	
543	                        // A shifted mod is dependent on this causal change if:
544	                        // - For Removed: shifted mod's reference position is after the removed position
545	                        // - For Inserted: shifted mod's current position is at or after the insert position
546	                        bool isDependent = causal.ChangeType == DiffChangeType.Removed
547	                            ? (shifted.ReferenceNumber.HasValue && shifted.ReferenceNumber.Value > (causal.ReferenceNumber ?? 0))
548	                            : (shifted.CurrentNumber.HasValue && shifted.CurrentNumber.Value >= (causal.CurrentNumber ?? 0));
549	
550	                        if (isDependent)
551	                        {
552	                            causal.DependentChanges.Add(shifted);
553	                            assignedShifted.Add(shifted);
554	                        }
555	                    }
556	                }
557	
558	                // Add any unassigned shifted mods as top-level Moved entries
559	                foreach (var shifted in shiftedLines)
560	                {
561	                    if (!assignedShifted.Contains(shifted))
562	                    {
563	                        result.Add(shifted);
564	                    }
565	                }
566	            }
567	
568	            return result;
569	        }
570	
571	        private static Dictionary<ModDiffModel, ModDiffModel> DetectReplacements(IReadOnlyList<ModDiffModel> diffs, out HashSet<ModDiffModel> matchedAdditions)
572	        {
573	            // Build dictionary of new mods by their current position
574	            var additionsByLine = new Dictionary<int, ModDiffModel>();
575	            foreach (var diff in diffs)
576	            {
577	                if (diff.IsNew && diff.CurrentNumber is int currentLine && !additionsByLine.ContainsKey(currentLine))
578	                {
579	                    additionsByLine[currentLine] = diff;
580	                }
581	            }
582	
583	            var replacements = new Dictionary<ModDiffModel, ModDiffModel>();
584	            var usedAdditions = new HashSet<ModDiffModel>();
585	
586	            // Get all removed mods sorted by reference position
587	            var removedMods = diffs
588	                .Where(d => d.IsRemoved && d.ReferenceNumber.HasValue)
589	                .OrderBy(d => d.ReferenceNumber!.Value)
590	                .ToList();
591	
592	            // First pass: Match exact positions (original behavior for no-shift scenarios)
593	            foreach (var diff in removedMods)
594	            {
595	                int referenceLine = diff.ReferenceNumber!.Value;
596	                
597	                if (additionsByLine.TryGetValue(referenceLine, out var candidate) && usedAdditions.Add(candidate))
598	                {
599	                    replacements[diff] = candidate;
600	                }

